import { sql } from 'drizzle-orm';
import {
  check,
  index,
  inet,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  text,
  timestamp,
  unique,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';

// Conventions: UUIDv7 primary keys generated by the application, timestamptz everywhere,
// status columns as text with CHECK constraints (portable, and easier to extend than PG enums).

const timestamptz = (name: string) => timestamp(name, { withTimezone: true, mode: 'date' });
const createdAt = () => timestamptz('created_at').notNull().defaultNow();
const updatedAt = () => timestamptz('updated_at').notNull().defaultNow();

// ---- user-scoped (not tenant-owned) ---------------------------------------------------------

export const users = pgTable(
  'users',
  {
    id: uuid('id').primaryKey(),
    email: text('email').notNull(),
    passwordHash: text('password_hash').notNull(),
    fullName: text('full_name').notNull(),
    status: text('status', { enum: ['active', 'disabled'] })
      .notNull()
      .default('active'),
    emailVerifiedAt: timestamptz('email_verified_at'),
    disabledAt: timestamptz('disabled_at'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    // Emails are normalised to lower case on input; the functional index is the backstop.
    uniqueIndex('users_email_lower_key').on(sql`lower(${table.email})`),
    check('users_status_check', sql`${table.status} in ('active', 'disabled')`),
  ],
);

export const sessions = pgTable(
  'sessions',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    activeOrganizationId: uuid('active_organization_id').references(() => organizations.id, {
      onDelete: 'set null',
    }),
    userAgent: text('user_agent'),
    ipAddress: inet('ip_address'),
    createdAt: createdAt(),
    lastSeenAt: timestamptz('last_seen_at').notNull().defaultNow(),
    expiresAt: timestamptz('expires_at').notNull(),
    revokedAt: timestamptz('revoked_at'),
    revokeReason: text('revoke_reason'),
  },
  (table) => [index('sessions_user_id_idx').on(table.userId)],
);

/**
 * One row per issued refresh token. Rows are never reused: rotation marks the presented token
 * used and inserts its successor, so a second presentation of the same token is detectable.
 */
export const refreshTokens = pgTable(
  'refresh_tokens',
  {
    id: uuid('id').primaryKey(),
    sessionId: uuid('session_id')
      .notNull()
      .references(() => sessions.id, { onDelete: 'cascade' }),
    tokenHash: text('token_hash').notNull().unique(),
    createdAt: createdAt(),
    expiresAt: timestamptz('expires_at').notNull(),
    usedAt: timestamptz('used_at'),
    replacedById: uuid('replaced_by_id'),
    revokedAt: timestamptz('revoked_at'),
  },
  (table) => [index('refresh_tokens_session_id_idx').on(table.sessionId)],
);

export const emailTokens = pgTable(
  'email_tokens',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    purpose: text('purpose', { enum: ['verify_email', 'reset_password'] }).notNull(),
    tokenHash: text('token_hash').notNull().unique(),
    expiresAt: timestamptz('expires_at').notNull(),
    usedAt: timestamptz('used_at'),
    createdAt: createdAt(),
  },
  (table) => [
    index('email_tokens_user_purpose_idx').on(table.userId, table.purpose),
    check(
      'email_tokens_purpose_check',
      sql`${table.purpose} in ('verify_email', 'reset_password')`,
    ),
  ],
);

// ---- tenant root and tenant-owned (Row Level Security) --------------------------------------

export const organizations = pgTable(
  'organizations',
  {
    id: uuid('id').primaryKey(),
    name: text('name').notNull(),
    slug: text('slug').notNull().unique(),
    status: text('status', { enum: ['active', 'suspended'] })
      .notNull()
      .default('active'),
    timezone: text('timezone').notNull().default('UTC'),
    currency: text('currency').notNull().default('USD'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    check('organizations_status_check', sql`${table.status} in ('active', 'suspended')`),
    check('organizations_currency_check', sql`${table.currency} ~ '^[A-Z]{3}$'`),
  ],
);

export const permissions = pgTable('permissions', {
  key: text('key').primaryKey(),
  description: text('description').notNull(),
});

export const roles = pgTable(
  'roles',
  {
    id: uuid('id').primaryKey(),
    key: text('key').notNull(),
    name: text('name').notNull(),
    description: text('description').notNull(),
    rank: integer('rank').notNull(),
    // NULL for the built-in system roles; reserved for organization-defined roles later.
    organizationId: uuid('organization_id').references(() => organizations.id, {
      onDelete: 'cascade',
    }),
  },
  (table) => [
    uniqueIndex('roles_system_key_key')
      .on(table.key)
      .where(sql`${table.organizationId} is null`),
    uniqueIndex('roles_organization_key_key')
      .on(table.organizationId, table.key)
      .where(sql`${table.organizationId} is not null`),
  ],
);

export const rolePermissions = pgTable(
  'role_permissions',
  {
    roleId: uuid('role_id')
      .notNull()
      .references(() => roles.id, { onDelete: 'cascade' }),
    permissionKey: text('permission_key')
      .notNull()
      .references(() => permissions.key, { onDelete: 'cascade' }),
  },
  (table) => [primaryKey({ columns: [table.roleId, table.permissionKey] })],
);

export const organizationMembers = pgTable(
  'organization_members',
  {
    id: uuid('id').primaryKey(),
    organizationId: uuid('organization_id')
      .notNull()
      .references(() => organizations.id, { onDelete: 'cascade' }),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    roleId: uuid('role_id')
      .notNull()
      .references(() => roles.id),
    status: text('status', { enum: ['active', 'suspended'] })
      .notNull()
      .default('active'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    unique('organization_members_org_user_key').on(table.organizationId, table.userId),
    // Target for composite (organization_id, id) foreign keys from other tenant tables.
    unique('organization_members_org_id_key').on(table.organizationId, table.id),
    index('organization_members_user_id_idx').on(table.userId),
    check('organization_members_status_check', sql`${table.status} in ('active', 'suspended')`),
  ],
);

export const invitations = pgTable(
  'invitations',
  {
    id: uuid('id').primaryKey(),
    organizationId: uuid('organization_id')
      .notNull()
      .references(() => organizations.id, { onDelete: 'cascade' }),
    email: text('email').notNull(),
    roleId: uuid('role_id')
      .notNull()
      .references(() => roles.id),
    tokenHash: text('token_hash').notNull().unique(),
    invitedByUserId: uuid('invited_by_user_id')
      .notNull()
      .references(() => users.id),
    expiresAt: timestamptz('expires_at').notNull(),
    acceptedAt: timestamptz('accepted_at'),
    revokedAt: timestamptz('revoked_at'),
    createdAt: createdAt(),
  },
  (table) => [
    // At most one open invitation per email per organization.
    uniqueIndex('invitations_open_email_key')
      .on(table.organizationId, sql`lower(${table.email})`)
      .where(sql`${table.acceptedAt} is null and ${table.revokedAt} is null`),
  ],
);

// ---- integration ------------------------------------------------------------------------------

export const outboxEvents = pgTable(
  'outbox_events',
  {
    id: uuid('id').primaryKey(),
    type: text('type').notNull(),
    version: integer('version').notNull(),
    occurredAt: timestamptz('occurred_at').notNull(),
    organizationId: uuid('organization_id'),
    actorId: uuid('actor_id'),
    correlationId: text('correlation_id').notNull(),
    causationId: uuid('causation_id'),
    payload: jsonb('payload').notNull(),
    publishedAt: timestamptz('published_at'),
  },
  (table) => [
    // The relay only ever scans unpublished rows.
    index('outbox_events_unpublished_idx')
      .on(table.occurredAt)
      .where(sql`${table.publishedAt} is null`),
  ],
);

export const schema = {
  users,
  sessions,
  refreshTokens,
  emailTokens,
  organizations,
  permissions,
  roles,
  rolePermissions,
  organizationMembers,
  invitations,
  outboxEvents,
};
export type IdentitySchema = typeof schema;
